185	  - [x] `seed-b-backend.Api/Application/OrderCreateResult.cs` neu:
186	    ```csharp
187	    using seed_b_backend.Api.Dtos;
188	
189	    namespace seed_b_backend.Api.Application;
190	
191	    public class OrderCreateResult
192	    {
193	        public bool Success { get; private init; }
194	        public OrderDto? Order { get; private init; }
195	        public string? ErrorMessage { get; private init; }
196	
197	        public static OrderCreateResult Ok(OrderDto order) => new() { Success = true, Order = order };
198	        public static OrderCreateResult Invalid(string errorMessage) => new() { Success = false, ErrorMessage = errorMessage };
199	    }
